INSERT INTO `projects` (`id`, `parent_id`, `project_code`, `name`, `description`, `fiscal_year_id`, `category_id`, `department_id`, `responsible_user_id`, `activity_type`, `objective`, `target_group`, `target_quantity`, `location`, `methodology`, `start_date`, `end_date`, `completion_date`, `planned_activity_count`, `actual_activity_count`, `budget`, `disbursed_amount`, `status`, `progress`, `progress_mode`, `problem_description`, `notes`, `created_at`, `updated_at`) VALUES
('1', NULL, 'PRJ-2568-001', 'โครงการพัฒนาคุณภาพชีวิตและส่งเสริมสุขภาพประชาชนแบบยั่งยืน', 'มุ่งเน้นการดูแลสุขภาพเชิงรุก การป้องกันโรค และยกระดับสุขภาวะของประชาชนทุกกลุ่มวัยในเขตเทศบาล', '2', '2', '2', '3', NULL, 'เพื่อส่งเสริมสุขภาวะที่ดีของประชาชนในเขตเทศบาล ลดอัตราการป่วยด้วยโรคไม่ติดต่อเรื้อรัง และสร้างระบบการดูแลสุขภาพที่เข้มแข็งในระดับชุมชน', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '1300000.00', '1276000.00', 'completed', '100.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-05 17:48:46'),
('2', NULL, 'PRJ-2568-002', 'โครงการยกระดับโครงสร้างพื้นฐานและเมืองน่าอยู่อัจฉริยะ', 'พัฒนาถนน ทางเท้า ระบบไฟฟ้าส่องสว่าง และโครงข่ายการสัญจรที่ปลอดภัยได้มาตรฐานสากล', '2', '1', '1', '4', NULL, 'เพื่อปรับปรุงและขยายโครงข่ายโครงสร้างพื้นฐานให้มีความมั่นคง ปลอดภัย สะดวกสบาย และรองรับการเติบโตทางเศรษฐกิจของเมือง', NULL, '0', NULL, NULL, '2024-11-01', '2025-08-31', NULL, '1', '0', '4950000.00', '3302000.00', 'in_progress', '64.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('3', NULL, 'PRJ-2568-003', 'โครงการบริหารจัดการขยะมูลฝอยและสิ่งปฏิกูล', 'ขับเคลื่อนเมืองสะอาด ลดปริมาณขยะมูลฝอยตั้งแต่ต้นทาง และส่งเสริมการคัดแยกขยะเพื่อรีไซเคิล', '2', '4', '2', '3', NULL, 'เพื่อลดปริมาณขยะมูลฝอยตกค้างในชุมชน ส่งเสริมการคัดแยกขยะตามหลัก 3Rs และบริหารจัดการสิ่งปฏิกูลให้ถูกต้องตามหลักสุขาภิบาล', NULL, '0', NULL, NULL, '2025-01-01', '2025-07-31', NULL, '1', '0', '530000.00', '320000.00', 'in_progress', '60.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('4', '1', 'SUB-2568-001-01', 'โครงการส่งเสริมสุขภาพผู้สูงอายุ', 'ตรวจสุขภาพประจำปี กายภาพบำบัดเบื้องต้น และให้ความรู้เรื่องโภชนาการสำหรับผู้สูงวัย', '2', '2', '2', '3', 'สาธารณสุข', 'เพื่อตรวจคัดกรองสุขภาพและส่งเสริมการดูแลตนเองของผู้สูงอายุในชุมชน', 'ผู้สูงอายุในเขตเทศบาล', '450', 'ศูนย์บริการสาธารณสุขเทศบาล', 'ประสานงาน รพ.สต. และจัดอบรมภาคปฏิบัติ', '2024-10-15', '2025-01-31', '2025-01-28', '3', '3', '300000.00', '300000.00', 'completed', '100.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('5', '1', 'SUB-2568-001-02', 'โครงการออกกำลังกายเพื่อสุขภาพ', 'จัดกิจกรรมเต้นแอโรบิก ลานเดิน-วิ่ง และอบรมผู้นำการออกกำลังกายชุมชน', '2', '2', '2', '3', 'สาธารณสุข', 'เพื่อรณรงค์ให้ประชาชนทุกเพศทุกวัยออกกำลังกายอย่างสม่ำเสมอ', 'ประชาชนทั่วไป', '800', 'ลานอเนกประสงค์สวนสาธารณะ', 'จ้างวิทยากรผู้นำเต้นและจัดกิจกรรมสัปดาห์ละ 3 วัน', '2024-11-01', '2025-06-30', '2026-09-04', '4', '4', '400000.00', '400000.00', 'completed', '100.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('6', '1', 'SUB-2568-001-03', 'โครงการส่งเสริมสุขภาพประชาชนและตรวจสารปนเปื้อนในอาหาร', 'สุ่มตรวจสารฟอร์มาลิน บอแรกซ์ สารฟอกขาว และจัดอบรมสุขาภิบาลอาหารแก่ผู้ค้า', '2', '2', '2', '3', 'สาธารณสุข', 'เพื่อคุ้มครองผู้บริโภคและสร้างมาตรฐานความปลอดภัยของอาหารในตลาดสดและร้านค้า', 'ผู้ประกอบการค้าอาหารและผู้บริโภค', '350', 'ตลาดสดเทศบาลและตลาดนัด', 'ลงพื้นที่เก็บตัวอย่างและใช้ชุดทดสอบเบื้องต้น (Test Kit)', '2024-12-01', '2025-05-31', '2026-09-04', '3', '3', '300000.00', '300000.00', 'completed', '100.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('7', '2', 'SUB-2568-002-01', 'โครงการปรับปรุงผิวจราจรแอสฟัลท์ติกคอนกรีต ซอยเทศบาล 1-5', 'ปูผิวทางแอสฟัลท์ติกคอนกรีตหนา 5 ซม. รวมระยะทาง 2.5 กิโลเมตร', '2', '1', '1', '4', 'โครงสร้างพื้นฐาน', 'เพื่อเพิ่มความปลอดภัยและสะดวกสบายในการสัญจรของประชาชน', 'ประชาชนผู้ใช้เส้นทางสัญจร', '3000', 'ซอยเทศบาล 1-5', 'ประกวดราคาอิเล็กทรอนิกส์ (e-bidding) และควบคุมงานก่อสร้าง', '2024-11-15', '2025-04-30', '2026-09-04', '3', '3', '2200000.00', '2200000.00', 'completed', '100.00', 'auto', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('8', '2', 'SUB-2568-002-02', 'โครงการติดตั้งไฟฟ้าแสงสว่างพลังงานแสงอาทิตย์ (Solar LED)', 'ติดตั้งเสาไฟส่องสว่างโซลาร์เซลล์ 150 ต้น ตามถนนสายรองและซอยเปลี่ยว', '2', '1', '1', '4', 'โครงสร้างพื้นฐาน', 'เพื่อเพิ่มแสงสว่างในจุดเสี่ยง ลดอุบัติเหตุ และประหยัดพลังงานไฟฟ้าของเทศบาล', 'ประชาชนในชุมชนรอบนอก', '2000', 'ถนนสายรองและซอยย่อย', 'จัดซื้อจัดจ้างตามระเบียบพัสดุและติดตั้งเสาพร้อมโคมไฟ 80 จุด', '2025-02-01', '2025-08-15', NULL, '4', '2', '1300000.00', '650000.00', 'in_progress', '50.00', 'manual', NULL, NULL, '2026-09-04 11:27:07', '2026-09-04 15:02:57'),
('24', NULL, 'PRJ-2568-004', 'โครงการส่งเสริมและพัฒนาการศึกษาปฐมวัยและการเรียนรู้ตลอดชีวิต', 'มุ่งเน้นพัฒนาคุณภาพศูนย์พัฒนาเด็กเล็กและโรงเรียนในสังกัดเทศบาล พร้อมจัดแหล่งเรียนรู้ชุมชน', '2', '3', '3', '1', NULL, 'เพื่อยกระดับมาตรฐานการศึกษาปฐมวัย พัฒนาทักษะที่จำเป็นในศตวรรษที่ 21 และเปิดโอกาสการเรียนรู้ที่เท่าเทียมสำหรับทุกคน', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '1180000.00', '885000.00', 'in_progress', '73.75', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('25', NULL, 'PRJ-2568-005', 'โครงการอนุรักษ์ ฟื้นฟู และสืบสานศิลปวัฒนธรรมประเพณีท้องถิ่น', 'ส่งเสริมการอนุรักษ์มรดกทางวัฒนธรรม ประเพณีสงกรานต์ ลอยกระทง และภูมิปัญญาท้องถิ่น', '2', '3', '3', '2', NULL, 'เพื่อสืบสานและอนุรักษ์ขนบธรรมเนียมประเพณีอันดีงามของท้องถิ่น ปลูกจิตสำนึกรักบ้านเกิด และส่งเสริมการท่องเที่ยวเชิงวัฒนธรรม', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '870000.00', '460000.00', 'in_progress', '50.00', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('26', NULL, 'PRJ-2568-006', 'โครงการเพิ่มประสิทธิภาพระบบป้องกันและบรรเทาสาธารณภัย', 'จัดเตรียมความพร้อมด้านเครื่องมือ อุปกรณ์กู้ภัย และการฝึกซ้อมแผนเผชิญเหตุดับเพลิงและอุทกภัย', '2', '1', '4', '4', NULL, 'เพื่อเสริมสร้างขีดความสามารถในการป้องกันและเผชิญเหตุสาธารณภัย ลดความสูญเสียต่อชีวิตและทรัพย์สินของประชาชนในเขตเทศบาล', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '750000.00', '534000.00', 'in_progress', '73.33', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:05:41'),
('27', NULL, 'PRJ-2568-007', 'โครงการส่งเสริมเศรษฐกิจสร้างสรรค์และการท่องเที่ยวชุมชน', 'ยกระดับผลิตภัณฑ์ชุมชน OTOP พัฒนาตลาดถนนคนเดิน และส่งเสริมการท่องเที่ยวเชิงวัฒนธรรม', '2', '5', '4', '5', NULL, 'เพื่อกระตุ้นเศรษฐกิจฐานราก สร้างงาน สร้างรายได้ให้แก่ผู้ประกอบการรายย่อย และขับเคลื่อนการท่องเที่ยววิถีชุมชนอย่างยั่งยืน', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '785000.00', '466000.00', 'in_progress', '56.25', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:16:21'),
('28', NULL, 'PRJ-2568-008', 'โครงการพัฒนาสวนสาธารณะและพื้นที่สีเขียวเพื่อปอดของเมือง', 'ปรับปรุงภูมิทัศน์สวนสุขภาพ เพิ่มพื้นที่ปลูกไม้ยืนต้น และสร้างลานกิจกรรมสำหรับประชาชน', '2', '4', '2', '3', NULL, 'เพื่อเพิ่มพื้นที่สีเขียวต่อประชากร ดูดซับฝุ่นมลพิษ PM 2.5 และสร้างพื้นที่สาธารณะที่มีคุณภาพสำหรับการพักผ่อนหย่อนใจของทุกครอบครัว', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '1020000.00', '792500.00', 'in_progress', '78.33', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('29', NULL, 'PRJ-2568-009', 'โครงการบริหารจัดการน้ำและขุดลอกคูคลองเพื่อแก้ไขปัญหาน้ำท่วม', 'ขุดลอกคูคลอง กำจัดวัชพืช และก่อสร้างสถานีสูบน้ำอัตโนมัติป้องกันน้ำท่วมขังในเขตเมือง', '2', '1', '1', '4', NULL, 'เพื่อเพิ่มประสิทธิภาพการระบายน้ำในเขตเมือง บรรเทาความเดือดร้อนจากปัญหาน้ำท่วมขังรอระบาย และฟื้นฟูระบบนิเวศคูคลองสาธารณะ', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '2040000.00', '1275000.00', 'has_problem', '70.00', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('30', NULL, 'PRJ-2568-010', 'โครงการปรับปรุงภูมิทัศน์เมืองและจัดระเบียบสายสื่อสาร', 'จัดระเบียบสายสื่อสารลงดินและจัดระเบียบป้ายโฆษณาเพื่อความสวยงามและความปลอดภัยของเมือง', '2', '1', '1', '4', NULL, 'เพื่อสร้างความเป็นระเบียบเรียบร้อย ปลอดภัยจากอุบัติภัยสายสื่อสาร และยกระดับภูมิทัศน์เมืองสู่ความเป็นเมืองน่าอยู่อย่างยั่งยืน', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '1160000.00', '775000.00', 'in_progress', '56.67', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('31', NULL, 'PRJ-2568-011', 'โครงการส่งเสริมสวัสดิการผู้พิการ ผู้ด้อยโอกาส และครอบครัวเปราะบาง', 'สงเคราะห์ผู้ยากไร้ จัดหาอุปกรณ์ช่วยความพิการ และเสริมทักษะอาชีพแก่กลุ่มเปราะบาง', '2', '5', '4', '3', NULL, 'เพื่อลดความเหลื่อมล้ำทางสังคม พัฒนาคุณภาพชีวิตของผู้พิการและผู้ป่วยติดเตียง และเสริมสร้างศักยภาพให้กลุ่มเปราะบางพึ่งพาตนเองได้', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '550000.00', '377000.00', 'in_progress', '73.33', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
('32', NULL, 'PRJ-2568-012', 'โครงการพัฒนานวัตกรรมดิจิทัลและการบริการประชาชนอัจฉริยะ (Smart City)', 'พัฒนาระบบรับเรื่องราวร้องทุกข์ออนไลน์ แอปพลิเคชันบริการประชาชน และจุดบริการอินเทอร์เน็ตชุมชน', '2', '1', '4', '1', NULL, 'เพื่อยกระดับการให้บริการภาครัฐสู่ระบบดิจิทัล เพิ่มความโปร่งใส สะดวกรวดเร็ว และตอบสนองต่อปัญหาของประชาชนได้อย่างทันท่วงที', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '1650000.00', '733000.00', 'in_progress', '65.00', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-05 22:33:36'),
('33', NULL, 'PRJ-2568-013', 'โครงการส่งเสริมเกษตรปลอดภัยและพัฒนาแหล่งอาหารชุมชน', 'ส่งเสริมการปลูกผักอินทรีย์ เกษตรคนเมือง และการแปรรูปผลผลิตเพื่อความมั่นคงทางอาหาร', '2', '5', '4', '5', NULL, 'เพื่อสนับสนุนให้ประชาชนเข้าถึงอาหารที่ปลอดภัย มีคุณค่าทางโภชนาการ และสร้างรายได้เสริมจากการทำเกษตรกรรมปลอดสารพิษในเขตเมือง', NULL, '0', NULL, NULL, '2024-10-01', '2025-09-30', NULL, '1', '0', '365000.00', '177000.00', 'in_progress', '53.33', 'manual', NULL, NULL, '2026-09-04 15:02:57', '2026-09-04 15:02:57'),
